var p=UnityEngine.Object.FindAnyObjectByType<CampusRift.CampusExplorer>();var cc=p.GetComponent<UnityEngine.CharacterController>();
return new{playing=UnityEngine.Application.isPlaying,position=p.transform.position.ToString(),scale=p.transform.lossyScale.ToString(),cc.radius,cc.height,center=cc.center.ToString(),cc.stepOffset,cc.skinWidth,doors=UnityEngine.Object.FindObjectsByType<CampusRift.CampusAutomaticDoor>().OrderBy(d=>UnityEngine.Vector3.Distance(d.doorway.center,p.transform.position)).Take(5).Select(d=>new{d.name,center=d.doorway.center.ToString(),size=d.doorway.size.ToString(),normal=d.normal.ToString(),d.OpenAmount}).ToArray(),colliders=UnityEngine.Physics.OverlapSphere(p.transform.position+UnityEngine.Vector3.up,.85f).Select(c=>new{c.name,type=c.GetType().Name,center=c.bounds.center.ToString(),size=c.bounds.size.ToString(),mesh=c is UnityEngine.MeshCollider?((UnityEngine.MeshCollider)c).sharedMesh.name:""}).ToArray()};
